pool Nodes(NodeId): Node;
struct Node { value: i64 }
result OpenPool { ok: Nodes, err: i64 }
result Insert { ok: NodeId, err: i64 }
result Read { ok: Node, err: i64 }
buffer B: i64;
result OpenBuffer { ok: B, err: i64 }
result Change { ok: bool, err: i64 }
result Work { ok: i64, err: i64 }
fn snapshot(heap: allocator) -> Read {
    let mut nodes = try acquire_pool<OpenPool>(heap, 1);
    let id = try insert_pool<Insert>(nodes, new Node { value: 42 });
    return read_pool<Read>(nodes, id);
}
fn work(heap: allocator) -> Work {
    let mut value = 0;
    arena heap as outer {
        arena outer as inner {
            let retained = try snapshot(inner);
            let mut buffer = try acquire_buffer<OpenBuffer>(inner, 2);
            discard try append_buffer<Change>(buffer, 8);
            borrow buffer[0..1] as view {
                value = retained.value + read_slice(view, 0);
            }
        }
    }
    return new Work.ok(value);
}
fn main(heap: allocator) -> i64 {
    match work(heap) { Work.ok(value) => { return value; }, Work.err(code) => { return code; } }
}

files.examples/structural-constraints.my:
struct Reading {
    value: i64
}
struct TaggedReading {
    tag: bool,
    value: i64
}
fn value < T: copy + field(value: i64) >(item: T) -> i64 {
    return read_field(item, value);
}
fn forward < U: copy + field(value: i64) >(item: U) -> i64 {
    return value::< U >(item);
}
domain Counter: i64 {
    fn make(n: i64) -> Counter {
        return wrap[Counter](n);
    }
    fn score(item: Counter) -> i64 effects() {
        return unwrap(item);
    }
}
fn score < T: copy + op(score(item: T) -> i64 effects()) >(item: T) -> i64 effects() {
    return T.score(item);
}
fn main() -> i64 {
    return value::< Reading >(new Reading {
        value: 2
    }) + forward::< TaggedReading >(new TaggedReading {
        tag: true,
        value: 3
    }) + score::< Counter >(Counter.make(7));
}

files.examples/source-json.my:
buffer Bytes: u8;
result Encoded {
    ok: Bytes,
    err: i64
}
struct Item {
    count: u64,
    ready: bool
}
result Decoded {
    ok: Item,
    err: i64
}
fn encode < T: codec >(heap: allocator, value: T) -> Encoded {
    return json_encode::< Encoded >(heap, value, 4096);
}
fn roundtrip(heap: allocator) -> Decoded {
    let bytes = try encode::< Item >(heap, new Item {
        count: 42u64,
        ready: true
    });
    return json_decode::< Decoded >(heap, bytes, 4096);
}
fn main(heap: allocator) -> i64 {
    match roundtrip(heap) {
        Decoded.ok(item) => {
            if item.ready {
                return i64(item.count);
            }
            return 0;
        },
        Decoded.err(code) => {
            return code;
        }
    }
}

