module main;
import std_json;
fn parse(heap: allocator) -> std_json::Parsed {
    let text = "{\"answer\":42}";
    let mut bytes = try acquire_buffer<std_json::Input>(heap, len(text));
    borrow text[0..len(text)] as view {
        let mut i = 0u64;
        while i < len_slice(view) {
            discard try append_buffer<std_json::Status>(bytes, read_slice(view, i));
            i += 1u64;
        }
    }
    return std_json::parse(heap, bytes, 4096);
}
fn main(heap: allocator) -> i64 {
    match parse(heap) {
        std_json::Parsed.err(code) => { return code; },
        std_json::Parsed.ok(document) => {
            borrow document[0..len_buffer(document)] as view {
                let answer = std_json::field(view, 1, "answer");
                return std_json::get(view, answer, 5);
            }
        }
    }
}

